    <!-- INFINITE CSS MARQUEE CONTAINER WITH DRAG / TOUCH SUPPORT -->
    <div class="custom-subcat-marquee-wrapper" data-marquee-container>
      <div class="custom-subcat-track">

        {%- comment -%} REPEAT 4 TIMES TO ENSURE TRACK IS ALWAYS FULL AND NEVER SHOWS BLANK SPACE {%- endcomment -%}
        {%- for i in (1..4) -%}
          {%- for block in section.blocks -%}
            {%- assign target_col = block.settings.collection -%}
            {%- assign target_prod = block.settings.product -%}

            {%- if target_col != blank -%}
              {%- assign display_url = target_col.url -%}
