                {%- assign hover_image = target_prod.media[1].preview_image -%}
              {%- endif -%}
            {%- endif -%}

            <div class="custom-subcat-slide" {% if i > 1 %}aria-hidden="true"{% endif %} {{ block.shopify_attributes }}>
