<script>
  document.addEventListener('DOMContentLoaded', function() {
    const wrapper = document.querySelector('#subcat-section-{{ section.id }} [data-marquee-container]');
    const track = document.querySelector('#subcat-section-{{ section.id }} .custom-subcat-track');
    if (!wrapper || !track) return;

    // Duplicamos una vez más el contenido internamente por JS para asegurar margen de maniobra
    track.innerHTML += track.innerHTML;

    let isDown = false;
    let startX;
    let scrollLeft;

    // Infinite loop correction on manual scroll/drag
    wrapper.addEventListener('scroll', function() {
      const maxScrollLeft = track.scrollWidth / 2;

      // Si llega al final del segundo bloque, salta al inicio de forma invisible
      if (wrapper.scrollLeft >= maxScrollLeft) {
        wrapper.scrollLeft = wrapper.scrollLeft - maxScrollLeft;
      } 
      // Si llega demasiado a la izquierda, salta hacia adelante
      else if (wrapper.scrollLeft <= 0) {
        wrapper.scrollLeft = maxScrollLeft + wrapper.scrollLeft;
      }
    });

    // Mouse drag support
    wrapper.addEventListener('mousedown', (e) => {
      isDown = true;
      wrapper.classList.add('is-dragging');
      startX = e.pageX - wrapper.offsetLeft;
      scrollLeft = wrapper.scrollLeft;
    });

    wrapper.addEventListener('mouseleave', () => {
      isDown = false;
      wrapper.classList.remove('is-dragging');
    });

    wrapper.addEventListener('mouseup', () => {
      isDown = false;
      wrapper.classList.remove('is-dragging');
    });

    wrapper.addEventListener('mousemove', (e) => {
      if (!isDown) return;
      e.preventDefault();
      const x = e.pageX - wrapper.offsetLeft;
      const walk = (x - startX) * 2;
      wrapper.scrollLeft = scrollLeft - walk;
    });
  });
</script>
