  </div>
</aside>

<!-- Snippet Global Quote Modal -->

<script>
  document.addEventListener('DOMContentLoaded', function() {
    const hamburgerBtn = document.getElementById('HeaderHamburger');
    const drawerCloseBtn = document.getElementById('MobileDrawerClose');
    const drawer = document.getElementById('MobileDrawer');
    const overlay = document.getElementById('MobileDrawerOverlay');
    if (!drawer || drawer.dataset.navigationReady) return;
    drawer.dataset.navigationReady = 'true';
    const mobileLayout = window.matchMedia('(max-width: 989px)');

    let previousOverflow = '';

    function openDrawer() {
      if (drawer && overlay && !drawer.classList.contains('is-open')) {
        previousOverflow = document.body.style.overflow;
        drawer.scrollTop = 0;
        drawer.removeAttribute('inert');
        drawer.setAttribute('aria-hidden', 'false');
        hamburgerBtn?.setAttribute('aria-expanded', 'true');
        drawer.classList.add('is-open');
        overlay.classList.add('is-open');
        document.body.style.overflow = 'hidden';
        drawerCloseBtn?.focus({ preventScroll: true });
      }
    }

    function closeDrawer(options = {}) {
      const quoteOpen = document.getElementById('QuoteModal')?.classList.contains('is-open');
      if (quoteOpen && !options.desktopTransition) return;
      if (drawer && overlay && drawer.classList.contains('is-open')) {
        drawer.classList.remove('is-open');
        overlay.classList.remove('is-open');
        drawer.setAttribute('inert', '');
        drawer.setAttribute('aria-hidden', 'true');
        hamburgerBtn?.setAttribute('aria-expanded', 'false');
        if (quoteOpen) {
          document.dispatchEvent(new CustomEvent('equipro:quote-menu-release', {
            detail: { previousOverflow }
          }));
          document.body.style.overflow = 'hidden';
        } else {
          document.body.style.overflow = previousOverflow;
          const target = [hamburgerBtn,
            document.querySelector('.site-header__actions [data-open-quote-modal]'),
            document.querySelector('.site-header__logo a')]
            .find(element => element && !element.closest('[inert]') && element.getClientRects().length &&
              getComputedStyle(element).visibility !== 'hidden');
          target?.focus({ preventScroll: true });
        }
      }
    }

    mobileLayout.addEventListener('change', event => {
      if (!event.matches) closeDrawer({ desktopTransition: true });
    });

    if (hamburgerBtn) hamburgerBtn.addEventListener('click', openDrawer);
    if (drawerCloseBtn) drawerCloseBtn.addEventListener('click', closeDrawer);
    if (overlay) overlay.addEventListener('click', closeDrawer);
    drawer?.addEventListener('keydown', event => {
      if (!drawer.classList.contains('is-open') || document.getElementById('QuoteModal')?.classList.contains('is-open')) return;
      if (event.key === 'Escape') {
        event.preventDefault();
        closeDrawer();
      } else if (event.key === 'Tab') {
        const controls = [...drawer.querySelectorAll('a[href], button, [tabindex]')]
          .filter(element => element.tabIndex >= 0 && !element.disabled && element.getClientRects().length);
        const index = controls.indexOf(document.activeElement);
        if (index === -1 || (event.shiftKey ? index === 0 : index === controls.length - 1)) {
          event.preventDefault();
          (event.shiftKey ? controls[controls.length - 1] : controls[0])?.focus({ preventScroll: true });
        }
      }
    });

    // Submenu Toggle en Mobile
    const subToggles = document.querySelectorAll('[data-sub-toggle]');
    subToggles.forEach(toggle => {
      toggle.addEventListener('click', function() {
        const submenu = this.closest('.mobile-drawer__has-sub')?.querySelector('.mobile-drawer__submenu');
        if (submenu) {
          submenu.classList.toggle('is-open');
          this.textContent = submenu.classList.contains('is-open') ? '−' : '+';
        }
      });
    });
  });
</script>

