.category-subnav {
  background-color: #ffffff;
  border-bottom: 1px solid #e5e5ea;
  position: relative;
  z-index: 90;
}

.category-subnav__bar {
  display: flex;
  align-items: center;
  gap: 2.2rem;
  list-style: none;
  margin: 0;
  padding: 0;
}

.category-subnav__bar-item {
  position: static; /* Necesario para que el mega menú abarque todo el ancho */
  padding: 0.9rem 0;
}

.category-subnav__bar-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 0.9rem;
  font-weight: 500;
  color: #1d1d1f;
  text-decoration: none;
  transition: color 0.15s ease;
}

.category-subnav__bar-link:hover,
.category-subnav__bar-item:hover .category-subnav__bar-link {
  color: #ab273b;
}

.category-subnav__bar-chevron {
  transition: transform 0.2s ease;
  opacity: 0.6;
}

.category-subnav__bar-item:hover .category-subnav__bar-chevron {
  transform: rotate(180deg);
  opacity: 1;
}

/* CONTAINER DEL MEGA MENÚ */
.category-megamenu {
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  width: 100%;
  background-color: #ffffff;
  border-top: 1px solid #f0f0f2;
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.05);
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.2s ease, visibility 0.2s ease;
  z-index: 100;
}

.category-subnav__bar-item:hover .category-megamenu {
  opacity: 1;
  visibility: visible;
}

.category-megamenu__container {
  display: flex;
  padding-top: 1.5rem;
  padding-bottom: 2.5rem;
  gap: 2rem;
  min-height: 420px;
}

/* COLUMNA IZQUIERDA (SIDEBAR) */
.category-megamenu__sidebar {
  width: 260px;
  flex-shrink: 0;
  border-right: 1px solid #f0f0f2;
  padding-right: 1rem;
}

.category-megamenu__sidebar-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.category-megamenu__sidebar-item {
  border-radius: 8px;
  transition: background-color 0.15s ease;
}

.category-megamenu__sidebar-item:hover,
.category-megamenu__sidebar-item.is-selected {
  background-color: #f4f4f6;
}

.category-megamenu__sidebar-link {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 14px;
  font-size: 0.88rem;
  font-weight: 500;
  color: #1d1d1f;
  text-decoration: none;
}

.category-megamenu__sidebar-arrow {
  opacity: 0.4;
  transition: transform 0.15s ease, opacity 0.15s ease;
}

.category-megamenu__sidebar-item.is-selected .category-megamenu__sidebar-arrow,
.category-megamenu__sidebar-item:hover .category-megamenu__sidebar-arrow {
  opacity: 1;
  transform: translateX(2px);
}

/* PANEL DERECHO (GRID DE CARDS) */
.category-megamenu__content {
  flex-grow: 1;
  padding-left: 1rem;
}

.category-megamenu__tab-panel {
  display: none;
}

.category-megamenu__tab-panel.is-active {
  display: block;
}

.category-megamenu__grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1.5rem;
}

/* TARJETAS ESTILO FOTO (CORREGIDO PARA UNIFICAR FONDOS) */
.category-megamenu__card {
  display: flex;
  flex-direction: column;
  text-decoration: none;
  gap: 10px;
}

.category-megamenu__card-image {
  background-color: #ffffff; /* Cambiado a blanco puro para fundir los fondos blancos y transparentes */
  border: 1px solid #f0f0f2;  /* Un borde sutil y elegante que enmarca cada producto */
  border-radius: 12px;
  aspect-ratio: 1 / 1;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  padding: 1.2rem;             /* Margen interno para que el producto respire */
  transition: border-color 0.2s ease, transform 0.2s ease;
}

.category-megamenu__card:hover .category-megamenu__card-image {
  border-color: #d1d1d6;
  transform: translateY(-2px);
}

.category-megamenu__card-image img {
  max-width: 100%;
  max-height: 100%;
  object-fit: contain;
}

.category-megamenu__card-placeholder {
  width: 100%;
  height: 100%;
  background-color: #eaeaea;
  border-radius: 8px;
}

.category-megamenu__card-title {
  font-size: 0.82rem;
  font-weight: 400; /* FUENTE DELGADA Y LIMPIA ABAJO */
  color: #1d1d1f;
  line-height: 1.3;
  transition: color 0.15s ease;
}

.category-megamenu__card:hover .category-megamenu__card-title {
  color: #ab273b;
}

.category-megamenu__direct-link {
  font-size: 0.95rem;
  font-weight: 600;
  color: #ab273b;
  text-decoration: none;
}

@media (max-width: 989px) {
  .category-megamenu__grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

/* ESTILOS PARA TARJETAS DISCOVER / PROMO CON IMAGEN */
.custom-promo-card .category-megamenu__card-image {
  position: relative;
}

.custom-promo-badge {
  position: absolute;
  top: 10px;
  left: 10px;
  background-color: #1d1d1f;
  color: #ffffff;
  font-size: 0.68rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  padding: 4px 8px;
  border-radius: 4px;
}

.promo-title {
  font-weight: 500 !important;
}

.category-megamenu__content.full-width-content {
  padding-left: 0;
  width: 100%;
}

.category-megamenu__content.full-width-content .category-megamenu__grid {
  grid-template-columns: repeat(5, 1fr);
}
